import React from 'react';
import {Divider} from 'antd';
import {ProForm, ProFormRadio} from '@ant-design/pro-form';
import {AvatarStamp, type RectZenithPlace} from '@yookue/ant-buddy-pro';


export default () => {
    const [placement, setPlacement] = React.useState<RectZenithPlace>('bottomRight');

    return (
        <>
            <ProForm
                name='AvatarStamp_demo.zh-CN'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='\u4F4D\u7F6E'
                    radioType='button'
                    fieldProps={{
                        value: placement,
                        buttonStyle: 'solid',
                        onChange: (event) => {
                            setPlacement(event.target?.value);
                        }
                    }}
                    options={[
                        {label: '\u5DE6\u4E0A\u89D2', value: 'topLeft'},
                        {label: '\u53F3\u4E0A\u89D2', value: 'topRight'},
                        {label: '\u5DE6\u4E0B\u89D2', value: 'bottomLeft'},
                        {label: '\u53F3\u4E0B\u89D2', value: 'bottomRight'},
                    ]}
                />
            </ProForm>
            <Divider/>
            <AvatarStamp
                src='https://gw.alipayobjects.com/zos/rmsportal/BiazfanxmamNRoxxVxka.png'
                placement={placement}
                size={96}
                addon={(
                    <span
                        style={{
                            color: '#fff',
                            backgroundColor: '#ffc53d',
                            fontSize: '12px',
                            borderRadius: '16px',
                            padding: '2px 6px',
                        }}
                    >
                        VIP
                    </span>
                )}
            />
        </>
    );
}
