import React from 'react';
import {Input, Divider} from 'antd';
import {ProForm, ProFormRadio, ProFormSwitch} from '@ant-design/pro-form';
import {LabelField, type AxisDirectionType} from '@yookue/ant-buddy-pro';
import {type LabelPresetStyle} from '@yookue/ant-buddy-pro/field/LabelField';


export default () => {
    const [layout, setLayout] = React.useState<AxisDirectionType>('horizontal');
    const [required, setRequired] = React.useState<boolean>(false);
    const [presetStyle, setPresetStyle] = React.useState<LabelPresetStyle | false>('field-prior');

    return (
        <>
            <ProForm
                name='LabelField_demo.zh-CN'
                layout='horizontal'
                autoFocusFirstInput={false}
                submitter={false}
            >
                <ProFormRadio.Group
                    label='\u5E03\u5C40'
                    radioType='button'
                    fieldProps={{
                        value: layout,
                        buttonStyle: 'solid',
                        onChange: (event) => {
                            setLayout(event.target?.value);
                            if (event.target?.value === 'vertical') {
                                setPresetStyle(false);
                            }
                        }
                    }}
                    options={[
                        {label: '\u6C34\u5E73', value: 'horizontal'},
                        {label: '\u5782\u76F4', value: 'vertical'},
                    ]}
                />
                <ProFormSwitch
                    label='\u5FC5\u586B'
                    checkedChildren='\u662F'
                    unCheckedChildren='\u5426'
                    fieldProps={{
                        checked: required,
                        onChange: setRequired,
                    }}
                />
                <ProFormRadio.Group
                    label='\u9884\u8BBE\u6837\u5F0F'
                    radioType='button'
                    fieldProps={{
                        value: presetStyle,
                        buttonStyle: 'solid',
                        disabled: layout !== 'horizontal',
                        onChange: (event) => {
                            setPresetStyle(event.target?.value);
                        }
                    }}
                    options={[
                        {label: '\u6807\u7B7E\u4F18\u5148', value: 'label-prior'},
                        {label: '\u5B57\u6BB5\u4F18\u5148', value: 'field-prior'},
                        {label: '\u65E0', value: false},
                    ]}
                />
            </ProForm>
            <Divider/>
            <LabelField
                label='\u7528\u6237\u540D'
                layout={layout}
                required={required}
                presetStyle={presetStyle}
            >
                <Input placeholder='\u7528\u6237\u540D'/>
            </LabelField>
        </>
    );
}
